  ('3de8cd6d-b109-402c-be0d-6ac1c6b562b4', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', '943a98cf-f191-4735-80ef-a37dfe6dda3e', 'concept'::public.curated_course_node_type, 'Sensitivity to demand variability and traffic', null, 1),
  ('70834844-8d7e-4b83-8ca1-2faa803f2bca', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', '943a98cf-f191-4735-80ef-a37dfe6dda3e', 'concept'::public.curated_course_node_type, 'Scenario planning and what-if analysis', null, 2),
  ('8af4fa01-b9f4-47fe-8d81-4bd947dc24b9', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', null, 'topic'::public.curated_course_node_type, 'Distribution Network Design', 'A logistics network determines where inventory sits, how orders flow, and how fast customers can be served. This topic builds network design judgment.', 5),
