  ('54fe6c72-b9f1-42f7-96a2-6fb21fc0f28c', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', 'd353cf78-64b6-461e-97f1-7ca1fe497a82', 'concept'::public.curated_course_node_type, 'Factories, suppliers, ports, DCs, cross-docks, stores, lockers, and customer nodes', null, 0),
