  ('eaec3e22-5acc-485e-a5a9-0a3019aef6fe', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', 'd353cf78-64b6-461e-97f1-7ca1fe497a82', 'concept'::public.curated_course_node_type, 'Single-echelon and multi-echelon networks', null, 2),
  ('2c1b40c1-a70a-4c32-8770-fd7ed1ea535c', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', '8af4fa01-b9f4-47fe-8d81-4bd947dc24b9', 'subtopic'::public.curated_course_node_type, 'Facility Location and Flow', 'The point is to locate facilities and routes around demand, cost, capacity, and service.', 1),
  ('4aa5ec3f-f573-4b5e-aa80-2ea20a107b12', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', '2c1b40c1-a70a-4c32-8770-fd7ed1ea535c', 'concept'::public.curated_course_node_type, 'Center-of-gravity, network optimization, and lane-flow modeling', null, 0),
  ('8af86266-b214-4cba-8e1f-b2973754b4d1', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', '2c1b40c1-a70a-4c32-8770-fd7ed1ea535c', 'concept'::public.curated_course_node_type, 'Inbound, outbound, reverse, and transfer flows', null, 1),
  ('234a7b8d-fd39-461a-92cd-7b29724e5b04', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', '2c1b40c1-a70a-4c32-8770-fd7ed1ea535c', 'concept'::public.curated_course_node_type, 'Capacity, labor, real estate, tax, risk, and customer-density considerations', null, 2),
  ('e35b8c43-564a-4c48-8bce-ff87ab4a7ffd', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', '8af4fa01-b9f4-47fe-8d81-4bd947dc24b9', 'subtopic'::public.curated_course_node_type, 'Network Strategy', 'Students connect network design to business strategy.', 2),
  ('c1a4775d-8af3-483f-866b-ea96f7a987cd', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', 'e35b8c43-564a-4c48-8bce-ff87ab4a7ffd', 'concept'::public.curated_course_node_type, 'Speed versus cost versus resilience', null, 0),
  ('f2430822-a741-4291-b785-48a7952b10d0', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', 'e35b8c43-564a-4c48-8bce-ff87ab4a7ffd', 'concept'::public.curated_course_node_type, 'Regionalization, nearshoring, and multi-sourcing', null, 1),
  ('fe45eaa2-4fb1-4d6e-94a5-9cf12ee8259d', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', 'e35b8c43-564a-4c48-8bce-ff87ab4a7ffd', 'concept'::public.curated_course_node_type, 'Network redesign triggers: growth, merger, disruption, service failure, and channel change', null, 2),
  ('3be74a70-643d-4611-99bd-006897d18d02', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', null, 'topic'::public.curated_course_node_type, 'Warehousing, Fulfillment and Inventory Interface', 'Transportation and warehousing are tightly linked: shipment size, order timing, storage design, and inventory policy all shape freight performance.', 6),
