  ('479cdbd8-3b5e-4168-b4e7-c8662b11a207', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', null, 'topic'::public.curated_course_node_type, 'Demand Planning, S&OP and Capacity Alignment', 'Logistics cannot perform well when demand, inventory, and capacity plans are disconnected. This section links transportation decisions to planning cadence.', 7),
