  ('ea77ad9f-0bf6-4d23-b1f3-285bd3e4d0cc', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', 'cadbf517-f3a1-49e9-a210-b57815ca2acc', 'concept'::public.curated_course_node_type, 'Moving averages, exponential smoothing, causal forecasts, and judgment overlays', null, 1),
  ('2ba6028e-ce2b-4ac6-b50b-af0c6a3e22c3', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', 'cadbf517-f3a1-49e9-a210-b57815ca2acc', 'concept'::public.curated_course_node_type, 'Forecast bias, accuracy, and exception review', null, 2),
  ('17b9b079-1f94-4fb0-9194-85e0d2271d62', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', '479cdbd8-3b5e-4168-b4e7-c8662b11a207', 'subtopic'::public.curated_course_node_type, 'S&OP and Logistics Capacity', 'The purpose is to align freight capacity, warehouse labor, and inventory with expected demand.', 1),
