  ('518e41c9-ebfd-4e5b-ac1d-115cf4f28650', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', 'fed4de7b-1d9f-471e-863d-983468564851', 'concept'::public.curated_course_node_type, 'Trade-offs among forecast accuracy, buffer inventory, and transport flexibility', null, 2),
