  ('e457f9b1-1d9e-446f-b7bf-4b67dd70cc05', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', '2646c3b1-6dbe-4f9a-b98a-3e40578d1f97', 'concept'::public.curated_course_node_type, 'Urban, suburban, and rural delivery economics', null, 2),
  ('5f82851f-c6ef-4ef6-9905-6cd4ca470b1c', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', '1531c922-6ad0-4867-866f-a61f02cefad9', 'subtopic'::public.curated_course_node_type, 'Customer Promise Design', 'The point is to design delivery promises that are attractive and operationally possible.', 1),
  ('f3c18350-cd03-480d-824b-0f370ce20a90', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', '5f82851f-c6ef-4ef6-9905-6cd4ca470b1c', 'concept'::public.curated_course_node_type, 'Delivery speed, accuracy, visibility, installation, returns, and communication', null, 0),
