  ('13ccfb0c-4d69-4bfa-83a8-ed84146fd26e', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', '5f82851f-c6ef-4ef6-9905-6cd4ca470b1c', 'concept'::public.curated_course_node_type, 'Customer experience metrics and failure recovery', null, 2),
