  ('0ecd41cd-548d-4c57-b445-8f0ee98ea58a', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', 'e8ec6480-369e-4c29-ba85-3f06bc71b975', 'concept'::public.curated_course_node_type, 'Return authorization, inspection, disposition, refurbish, recycle, and resale', null, 0),
