  ('70d541bf-0911-437e-bde7-a12965768ecf', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', '5ffff245-5218-4e33-b4dc-e07b8ff44114', 'concept'::public.curated_course_node_type, 'Risk probability, impact, detectability, and velocity', null, 2),
