  ('99210d28-14ec-4f64-83cc-8fa7e2511ed2', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', 'b19a50b6-ab7b-4a78-8ffc-02652eaaf7a3', 'concept'::public.curated_course_node_type, 'Redundant carriers, alternate ports, safety capacity, inventory buffers, and flexible routing', null, 0),
  ('8ef84776-68b4-4b99-8361-22ab06da036c', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', 'b19a50b6-ab7b-4a78-8ffc-02652eaaf7a3', 'concept'::public.curated_course_node_type, 'Scenario planning, playbooks, and business continuity planning', null, 1),
  ('78e57d5e-9dd5-4a0e-8040-9d29cc1796fb', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', 'b19a50b6-ab7b-4a78-8ffc-02652eaaf7a3', 'concept'::public.curated_course_node_type, 'Trade-offs among efficiency, resilience, and working capital', null, 2),
  ('de59c4b0-3e58-4d96-a0d5-3ce746050eda', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', '96a426f3-a2d5-4921-ae5f-defcfcbe54e1', 'subtopic'::public.curated_course_node_type, 'Disruption Response', 'Students learn the operating discipline of crisis logistics.', 2),
  ('790759ef-6ae0-4d17-b06d-ca1cac4a4555', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', 'de59c4b0-3e58-4d96-a0d5-3ce746050eda', 'concept'::public.curated_course_node_type, 'War rooms, escalation, decision rights, communications, and recovery priorities', null, 0),
  ('e9a4d297-e900-4a7b-91aa-5ffd4c627ff8', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', 'de59c4b0-3e58-4d96-a0d5-3ce746050eda', 'concept'::public.curated_course_node_type, 'Expediting, allocation, substitution, and customer segmentation during disruption', null, 1),
  ('56ee1fe4-a7e4-4900-9b80-33693cea9f05', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', 'de59c4b0-3e58-4d96-a0d5-3ce746050eda', 'concept'::public.curated_course_node_type, 'Post-event learning and resilience investment cases', null, 2),
  ('ddcc295a-6538-44da-8cf8-99f443ac7be2', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', null, 'topic'::public.curated_course_node_type, 'Sustainable and Responsible Logistics', 'Logistics choices affect emissions, communities, labor, safety, and waste. This section makes sustainability an operational design problem.', 15),
  ('bc1a7a4e-99f8-45c0-bc91-7b00be61c46e', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', 'ddcc295a-6538-44da-8cf8-99f443ac7be2', 'subtopic'::public.curated_course_node_type, 'Emissions and Energy', 'Students learn where logistics emissions come from and how to reduce them.', 0),
  ('dd0701dc-e368-4dc6-a537-593bb7b96a3a', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', 'bc1a7a4e-99f8-45c0-bc91-7b00be61c46e', 'concept'::public.curated_course_node_type, 'Scope 1, Scope 2, and Scope 3 logistics emissions', null, 0),
  ('fa4e2ce1-7764-44fc-987d-b3babd8134a2', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', 'bc1a7a4e-99f8-45c0-bc91-7b00be61c46e', 'concept'::public.curated_course_node_type, 'Mode shift, route optimization, load factor, alternative fuels, EVs, and renewable energy', null, 1),
  ('34891231-709f-4e2e-b32f-4858d8431f15', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', 'bc1a7a4e-99f8-45c0-bc91-7b00be61c46e', 'concept'::public.curated_course_node_type, 'Carbon accounting, emissions factors, and customer reporting', null, 2);
