  ('7bfc2211-78b7-4478-8116-6b6c2a4a3159', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', 'ddcc295a-6538-44da-8cf8-99f443ac7be2', 'subtopic'::public.curated_course_node_type, 'Circular and Reverse Logistics', 'The focus is on recovering value and reducing waste.', 1),
