  ('9848f928-e98e-42fa-a3c6-062f1463a4e7', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', '64787e5a-cd29-4327-9f04-aaffcad558ce', 'concept'::public.curated_course_node_type, 'Driver safety, labor practices, warehouse ergonomics, and fair scheduling', null, 0),
  ('d1aa1e8c-c99e-4e6c-810b-0362e19f5ff6', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', '64787e5a-cd29-4327-9f04-aaffcad558ce', 'concept'::public.curated_course_node_type, 'Community impacts of freight, congestion, noise, and air quality', null, 1),
  ('c4cb41a0-9ead-458e-9468-9283ecd95a3d', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', '64787e5a-cd29-4327-9f04-aaffcad558ce', 'concept'::public.curated_course_node_type, 'Ethical sourcing, transparency, and supplier/carrier standards', null, 2),
