  ('b97fbfd6-e96b-41fd-9176-a5243c7e990f', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', '6fde868b-b4f8-4124-a3f7-f9d14e6fbd7a', 'concept'::public.curated_course_node_type, 'Motor carrier authority, hours of service, ELDs, hazardous materials, and safety ratings', null, 0),
