  ('76298ab3-17ed-4812-a61c-b86c87c639d3', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', '6fde868b-b4f8-4124-a3f7-f9d14e6fbd7a', 'concept'::public.curated_course_node_type, 'FMCSA, DOT, FMC, FAA, TSA, and international bodies', null, 2),
