  ('7adda5bf-5534-45b3-a253-ad813fe1f18a', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', 'fbe05152-227d-429e-97b2-fa949c9ca480', 'concept'::public.curated_course_node_type, 'Driver safety, warehouse safety, loading securement, hazmat handling, and incident reporting', null, 0),
