  ('7d741b3e-600c-4729-a757-0b44aad59bda', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', '969bb369-8b4d-4b35-b0fb-4b6b7f39557c', 'concept'::public.curated_course_node_type, 'Contracts, fraud, cargo theft, bribery, sanctions, antitrust, and confidentiality', null, 0),
