  ('d8e6ac3c-91ff-4e98-8dd6-f797fce85cdf', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', '969bb369-8b4d-4b35-b0fb-4b6b7f39557c', 'concept'::public.curated_course_node_type, 'Ethical decision making under service and cost pressure', null, 2),
