  ('72d21274-9d67-45e7-81be-477a5ab57dd2', 'f4a5b6c7-8d9e-4f46-9a66-6b7c8d9e0f86', 'd0f9096c-bf97-4b5b-9791-29bd442880b5', 'concept'::public.curated_course_node_type, 'Current network, lanes, modes, volumes, costs, service failures, and constraints', null, 0),
